### Cài đặt thuật toán

```
#include <iostream> 
using namespace std;
int Sequential_Search( int A[], int n, int x){
       for(int i=0; i<n; i++){
              if ( x == A[i]) 
                return i;
       }
       return -1;
}
int main(void){
       int A[] = {9, 7, 12, 8, 6, 5};
       int x = 15, n = 
       sizeof(A)/sizeof(A[0]); int t = 
       Sequential_Search(A,n,x); 
       if(t>=0)cout<<"\n Vị trí của x:"<<t; 
       else cout<<"\n Không tìm thấy x";
}
```

